function setPhoneState(state,message){
 phoneState=state;const badge=$('#phone-state');if(!badge)return;badge.textContent=message||state;badge.className='badge '+(state==='registered'?'ready':state==='ringing'?'configured':'unavailable');
 const ready=state==='registered';$('#phone-call').disabled=!ready;$('#phone-answer').disabled=state!=='ringing';$('#phone-hangup').disabled=!['ringing','calling','active'].includes(state);$('#phone-mute').disabled=state!=='active';$('#phone-hold').disabled=state!=='active';
}
async function connectPhone(){
 const extension=$('#phone-extension').value,password=$('#phone-password').value;if(!extension||!password){setPhoneState('offline','Extension and password required');return}
 if(!window.SIP?.Web?.SimpleUser){setPhoneState('offline','SIP runtime unavailable');return}
 try{
  setPhoneState('connecting','Connecting…');const cfg=await api('/webrtc/'+extension);const audio=$('#remote-audio'),input=$('#audio-input')?.value||'',output=$('#audio-output')?.value||'';if(output&&audio.setSinkId)await audio.setSinkId(output);localStorage.icpaasAudioInput=input;localStorage.icpaasAudioOutput=output;
  phone=new SIP.Web.SimpleUser(cfg.webSocketUrl,{aor:cfg.uri,media:{constraints:{audio:input?{deviceId:{exact:input}}:true,video:false},remote:{audio}},userAgentOptions:{authorizationUsername:extension,authorizationPassword:password,sessionDescriptionHandlerFactoryOptions:{peerConnectionConfiguration:{iceServers:cfg.iceServers}}},delegate:{onCallReceived:()=>setPhoneState('ringing','Incoming call'),onCallAnswered:()=>setPhoneState('active','In call'),onCallHangup:()=>setPhoneState('registered','Registered')}});
  await phone.connect();await phone.register();setPhoneState('registered','Registered');
 }catch(err){phone=null;setPhoneState('offline',err.message||'Registration failed')}
}
async function initializeMediaDevices(){
 const input=$('#audio-input'),output=$('#audio-output');if(!input||!output||!navigator.mediaDevices?.enumerateDevices)return;
 try{const devices=await navigator.mediaDevices.enumerateDevices(),savedInput=localStorage.icpaasAudioInput||input.value,savedOutput=localStorage.icpaasAudioOutput||output.value;input.innerHTML='<option value="">System default</option>';output.innerHTML='<option value="">System default</option>';for(const d of devices){const select=d.kind==='audioinput'?input:d.kind==='audiooutput'?output:null;if(!select)continue;const option=document.createElement('option');option.value=d.deviceId;option.textContent=d.label||`${d.kind==='audioinput'?'Microphone':'Speaker'} ${select.options.length}`;select.append(option)}input.value=[...input.options].some(x=>x.value===savedInput)?savedInput:'';output.value=[...output.options].some(x=>x.value===savedOutput)?savedOutput:''}catch(e){$('#media-result').innerHTML=`<span class="failed">Device discovery failed: ${esc(e.message)}</span>`}
}
async function runMediaDiagnostic(){
 const result=$('#media-result'),button=$('#media-test'),extension=$('#phone-extension').value;button.disabled=true;result.innerHTML='<span>Requesting microphone permission…</span>';
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw Error('Secure browser media API unavailable');
  activeInputStream?.getTracks().forEach(x=>x.stop());const input=$('#audio-input').value;activeInputStream=await navigator.mediaDevices.getUserMedia({audio:input?{deviceId:{exact:input}}:true,video:false});
  await initializeMediaDevices();const track=activeInputStream.getAudioTracks()[0],settings=track.getSettings(),output=$('#audio-output').value,audio=$('#remote-audio');let speaker='System default';if(output){if(!audio.setSinkId)throw Error('Speaker selection is not supported by this browser');await audio.setSinkId(output);speaker=$('#audio-output').selectedOptions[0]?.textContent||'Selected'}
  if(!extension)throw Error('Select an endpoint to test ICE/TURN');const cfg=await api('/webrtc/'+extension),ice=await probeIce(cfg.iceServers);localStorage.icpaasAudioInput=$('#audio-input').value;localStorage.icpaasAudioOutput=output;
  result.innerHTML=`<span class="passed">Microphone: ${esc(track.label||'available')} · ${settings.sampleRate||'auto'} Hz</span><span class="passed">Speaker: ${esc(speaker)}</span><span class="${ice.relay?'passed':'warning'}">ICE: ${ice.types.join(', ')||'none'} · TURN relay ${ice.relay?'available':'not confirmed'}</span>`;
 }catch(e){result.innerHTML=`<span class="failed">Diagnostic failed: ${esc(e.message)}</span>`}finally{activeInputStream?.getTracks().forEach(x=>x.stop());activeInputStream=null;button.disabled=false}
}
async function probeIce(iceServers){
 const pc=new RTCPeerConnection({iceServers,iceCandidatePoolSize:1}),types=new Set();pc.createDataChannel('diagnostic');pc.onicecandidate=e=>{if(!e.candidate)return;const type=e.candidate.type||String(e.candidate.candidate).match(/ typ (host|srflx|prflx|relay)/)?.[1];if(type)types.add(type)};try{await pc.setLocalDescription(await pc.createOffer());await new Promise(resolve=>{const timer=setTimeout(resolve,6000);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve()}}})}finally{pc.close()}return{types:[...types],relay:types.has('relay')};
}
async function placeCall(){const number=$('#dial-number').value.trim();if(!phone||!number)return;try{setPhoneState('calling','Checking compliance…');await post('/contact-center/compliance/check',{phoneNumber:number});setPhoneState('calling','Calling…');await phone.call(number)}catch(e){setPhoneState('registered',e.message)}}
async function answerCall(){try{await phone.answer();setPhoneState('active','In call')}catch(e){setPhoneState('ringing',e.message)}}
async function hangupCall(){try{await phone.hangup()}finally{setPhoneState('registered','Registered')}}
function toggleMute(){const pc=phone?.session?.sessionDescriptionHandler?.peerConnection;muted=!muted;pc?.getSenders().forEach(s=>{if(s.track?.kind==='audio')s.track.enabled=!muted});$('#phone-mute').textContent=muted?'Unmute':'Mute'}
async function toggleHold(){if(!phone?.hold)return;await phone.hold();$('#phone-hold').textContent='Resume'}
async function calls(){const rows=await api('/calls');shell('Live calls','Normalized call state across all engines.',`<section class="panel"><div class="table"><b>Call</b><b>Direction</b><b>From</b><b>To</b><b>Engine</b><b>State</b>${rows.flatMap(c=>[`<span>${c.id.slice(0,8)}</span>`,`<span>${esc(c.direction)}</span>`,`<span>${mask(c.from_number)}</span>`,`<span>${mask(c.to_number)}</span>`,`<span>${esc(c.engine_type)}</span>`,`<span class="badge">${esc(c.state)}</span>`]).join('')}</div></section>`)}function mask(x=''){return x.length>4?'••••'+x.slice(-4):'••••'}
